#!/usr/bin/env bun

import { join, relative } from "node:path";
import { stat } from "node:fs/promises";

import {
  analyzeServerActionsShape,
  checkServerActionGraphAsync,
} from "./validate-server-actions";

function arg(name: string): string | undefined {
  const flag = `--${name}=`;
  for (const raw of process.argv.slice(2)) {
    if (raw.startsWith(flag)) {
      return raw.slice(flag.length);
    }
  }
  return undefined;
}

const serverDir = arg("server-dir");
if (!serverDir) {
  process.stderr.write("usage: validate-server-actions.js --server-dir=<path>\n");
  process.exit(2);
}

async function main(): Promise<number> {
  try {
    const dirStat = await stat(serverDir!).catch(() => null);
    if (!dirStat || !dirStat.isDirectory()) {
      process.stdout.write(
        JSON.stringify({
          ok: true,
          files: 0,
          clientOnly: true,
          hasServerActions: false,
        }) + "\n",
      );
      return 0;
    }
    const violation = await checkServerActionGraphAsync(serverDir!);
    if (violation !== null) {
      process.stderr.write(
        `${relative(serverDir!, violation.filePath)}: ${violation.reason}\n`,
      );
      return 1;
    }

    // Classify the artifact as client-only (inert, zero-action) or
    // server-backed. The result is daemon-owned downstream: the build pipeline
    // reads it from stdout and persists `has_server_actions`, which gates the
    // local action worker and Cloudflare sharing.
    const actionsSource = await Bun.file(join(serverDir!, "src", "actions.ts"))
      .text()
      .catch(() => "");
    const shape = analyzeServerActionsShape(actionsSource);

    // A client-only artifact has no server surface at all, so it must not ship
    // a privileged implementation. Reject rather than silently ignore it.
    if (shape.clientOnly) {
      const privilegedStat = await stat(
        join(serverDir!, "src", "privileged.ts"),
      ).catch(() => null);
      if (privilegedStat?.isFile()) {
        process.stderr.write(
          "client-only web artifact (no server actions) must not include " +
            "server/src/privileged.ts; remove it, or add a server action to " +
            "make this a server-backed artifact.\n",
        );
        return 1;
      }
    }

    process.stdout.write(
      JSON.stringify({
        ok: true,
        clientOnly: shape.clientOnly,
        hasServerActions: !shape.clientOnly,
      }) + "\n",
    );
    return 0;
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    process.stderr.write(`validate-server-actions fatal: ${message}\n`);
    return 2;
  }
}

main().then(
  (code) => process.exit(code),
  (err) => {
    process.stderr.write(`validate-server-actions fatal: ${String(err)}\n`);
    process.exit(2);
  },
);

import { existsSync, statSync } from "node:fs";
import {
  basename,
  dirname,
  extname,
  join,
  normalize,
  relative,
  resolve,
} from "node:path";

export const REASON_IMPORT_PRIVILEGED_IMPLEMENTATION =
  "web artifact action code must not import `server/src/privileged.ts`. " +
  "Import descriptors from `@space/privileged` and call `ctx.executePrivileged(...)` instead.";

export const REASON_HOST_MODULE_IMPORT =
  "web artifact action code must not import Node/Bun host modules. " +
  "Move host-only behavior into `server/src/privileged.ts` and expose it through a typed privileged function.";

export const REASON_PROCESS_GLOBAL =
  "web artifact action code must not read the `process` global. " +
  "Use the fixed ctx API, or move host-only behavior into a privileged function.";

export const REASON_BUN_GLOBAL =
  "web artifact action code must not read the `Bun` global. " +
  "Use the fixed ctx API, or move host-only behavior into a privileged function.";

export const REASON_REQUIRE_CALL =
  "web artifact action code must not call `require(...)`. " +
  "Use static portable imports, or move host-only behavior into a privileged function.";

export const REASON_DYNAMIC_IMPORT =
  "web artifact action code must not call dynamic `import(...)`. " +
  "Use static portable imports so the build can validate portability.";

export const REASON_SUBPROCESS_API =
  "web artifact action code must not use subprocess APIs. " +
  "Move subprocess or host-command behavior into `server/src/privileged.ts`.";

export const REASON_EVAL_API =
  "web artifact action code must not use eval-like dynamic code execution.";

const HOST_MODULES = new Set([
  "bun",
  "bun:ffi",
  "bun:jsc",
  "child_process",
  "cluster",
  "crypto",
  "dns",
  "fs",
  "fs/promises",
  "module",
  "net",
  "node:child_process",
  "node:cluster",
  "node:crypto",
  "node:dns",
  "node:fs",
  "node:fs/promises",
  "node:module",
  "node:net",
  "node:os",
  "node:path",
  "node:process",
  "node:readline",
  "node:stream",
  "node:tls",
  "node:url",
  "node:util",
  "node:vm",
  "node:worker_threads",
  "os",
  "path",
  "process",
  "readline",
  "stream",
  "tls",
  "url",
  "util",
  "vm",
  "worker_threads",
]);

export interface ServerActionViolation {
  readonly filePath: string;
  readonly reason: string;
}

interface ImportReference {
  readonly specifier: string;
  readonly typeOnly: boolean;
}

export async function checkServerActionGraphAsync(
  serverDir: string,
): Promise<ServerActionViolation | null> {
  const root = resolve(serverDir);
  const entry = join(root, "src", "actions.ts");
  if (!existsSync(entry)) {
    return null;
  }

  const stack = [entry];
  const seen = new Set<string>();
  while (stack.length > 0) {
    const filePath = stack.pop()!;
    const canonical = resolve(filePath);
    if (seen.has(canonical)) {
      continue;
    }
    seen.add(canonical);

    const content = await Bun.file(canonical).text();
    const sourceViolation = checkServerActionSource(content);
    if (sourceViolation !== null) {
      return { filePath: canonical, reason: sourceViolation };
    }

    for (const ref of collectImportReferences(stripComments(content))) {
      if (isHostModuleSpecifier(ref.specifier)) {
        return { filePath: canonical, reason: REASON_HOST_MODULE_IMPORT };
      }
      if (ref.typeOnly) {
        continue;
      }
      if (!isRelativeSpecifier(ref.specifier)) {
        continue;
      }
      const target = resolveImport(canonical, ref.specifier);
      if (target === null) {
        continue;
      }
      if (!isWithin(root, target)) {
        continue;
      }
      if (isPrivilegedImplementationPath(target)) {
        return {
          filePath: canonical,
          reason: REASON_IMPORT_PRIVILEGED_IMPLEMENTATION,
        };
      }
      stack.push(target);
    }
  }
  return null;
}

export interface ServerActionsShape {
  /// True only when the entry actions module is *provably* a no-op: it declares
  /// zero server actions and performs no side effects when imported/executed.
  /// This is the only shape allowed to be served client-only and shared to
  /// Cloudflare. Anything we cannot prove inert reports `false` (server-backed),
  /// which is the safe direction: it runs a local worker and is not
  /// Cloudflare-shareable.
  readonly clientOnly: boolean;
  /// Diagnostic for why the module was treated as server-backed; null when
  /// `clientOnly` is true.
  readonly reason: string | null;
}

// `<ident-or-close>(` — any function/constructor call. An inert client-only
// module performs none (no `fetch()`, no IIFE, no `Object.freeze({})`, no
// `defineAction(...)`).
const CALL_EXPRESSION = /[A-Za-z0-9_$)\]]\s*\(/;
// Top-level statements that run code on import.
const EXECUTABLE_KEYWORD = /\b(throw|await|delete|yield|for|while|if|switch|do|new)\b/;
// The canonical empty actions export: `export const Actions = {} satisfies X;`
// (optional type annotation, optional `satisfies`, optional trailing `;`).
const EMPTY_ACTIONS_EXPORT =
  /\bexport\s+const\s+Actions\s*(?::\s*[^=;]+)?=\s*\{\s*\}\s*(?:satisfies\s+[^;]+)?;?/;

/// Classify the entry `server/src/actions.ts` source as a client-only (inert,
/// zero-action) module or a server-backed one. Fail-safe by construction: only
/// the minimal canonical empty module is reported client-only; any value
/// import, function call, tagged template, control-flow keyword, or non-empty
/// `Actions` literal reports server-backed. This proof runs WITHOUT executing
/// the module, so a side-effecting module is never run to classify it.
export function analyzeServerActionsShape(content: string): ServerActionsShape {
  const stripped = stripCommentsAndStrings(content);
  if (!EMPTY_ACTIONS_EXPORT.test(stripped)) {
    return { clientOnly: false, reason: "module exports server actions" };
  }
  for (const ref of collectImportReferences(stripComments(content))) {
    if (!ref.typeOnly) {
      return {
        clientOnly: false,
        reason: "module imports runtime (value) modules",
      };
    }
  }
  // Template literals are blanked by `stripCommentsAndStrings`, so a tagged
  // template call would slip past CALL_EXPRESSION; reject any backtick instead.
  if (/`/.test(stripComments(content))) {
    return { clientOnly: false, reason: "module uses template literals" };
  }
  if (CALL_EXPRESSION.test(stripped)) {
    return { clientOnly: false, reason: "module contains a function call" };
  }
  if (EXECUTABLE_KEYWORD.test(stripped)) {
    return {
      clientOnly: false,
      reason: "module contains top-level executable statements",
    };
  }
  return { clientOnly: true, reason: null };
}

export function checkServerActionSource(content: string): string | null {
  const stripped = stripCommentsAndStrings(content);
  if (/\bprocess\b/.test(stripped)) {
    return REASON_PROCESS_GLOBAL;
  }
  if (/\bBun\b/.test(stripped)) {
    return REASON_BUN_GLOBAL;
  }
  if (/\brequire\s*\(/.test(stripped)) {
    return REASON_REQUIRE_CALL;
  }
  if (/\bimport\s*\(/.test(stripped)) {
    return REASON_DYNAMIC_IMPORT;
  }
  if (
    /\b(spawn|spawnSync|exec|execFile|execFileSync|execSync)\s*\(/.test(
      stripped,
    )
  ) {
    return REASON_SUBPROCESS_API;
  }
  if (/\b(eval|Function)\s*\(/.test(stripped)) {
    return REASON_EVAL_API;
  }
  return null;
}

function collectImportReferences(source: string): ImportReference[] {
  const refs: ImportReference[] = [];
  const importFrom =
    /\bimport\s+(type\s+)?(?:[^'";]*?\s+from\s+)?["']([^"']+)["']/g;
  let match: RegExpExecArray | null;
  while ((match = importFrom.exec(source)) !== null) {
    refs.push({
      specifier: match[2]!,
      typeOnly: match[1] !== undefined,
    });
  }

  const exportFrom =
    /\bexport\s+(type\s+)?(?:[^'";]*?\s+from\s+)["']([^"']+)["']/g;
  while ((match = exportFrom.exec(source)) !== null) {
    refs.push({
      specifier: match[2]!,
      typeOnly: match[1] !== undefined,
    });
  }
  return refs;
}

function isRelativeSpecifier(specifier: string): boolean {
  return specifier.startsWith("./") || specifier.startsWith("../");
}

function isHostModuleSpecifier(specifier: string): boolean {
  return (
    specifier.startsWith("node:") ||
    specifier.startsWith("bun:") ||
    HOST_MODULES.has(specifier)
  );
}

function isPrivilegedImplementationPath(path: string): boolean {
  const normalized = normalize(path);
  return basename(normalized) === "privileged.ts";
}

function resolveImport(importerPath: string, specifier: string): string | null {
  const base = resolve(dirname(importerPath), specifier);
  const candidates = [];
  if (extname(base) !== "") {
    candidates.push(base);
  } else {
    candidates.push(`${base}.ts`, `${base}.tsx`, `${base}.js`, join(base, "index.ts"));
  }
  for (const candidate of candidates) {
    try {
      const stats = statSync(candidate);
      if (stats.isFile()) {
        return resolve(candidate);
      }
    } catch {
      continue;
    }
  }
  return null;
}

function isWithin(root: string, candidate: string): boolean {
  const rel = relative(root, candidate);
  return rel === "" || (!rel.startsWith("..") && !rel.startsWith("/"));
}

function stripComments(source: string): string {
  const out: string[] = [];
  let i = 0;
  const n = source.length;
  while (i < n) {
    const c = source[i]!;
    const next = source[i + 1];
    if (c === "/" && next === "/") {
      out.push("  ");
      i += 2;
      while (i < n && source[i] !== "\n") {
        out.push(" ");
        i++;
      }
      continue;
    }
    if (c === "/" && next === "*") {
      out.push("  ");
      i += 2;
      while (i < n && !(source[i] === "*" && source[i + 1] === "/")) {
        out.push(source[i] === "\n" ? "\n" : " ");
        i++;
      }
      if (i < n) {
        out.push("  ");
        i += 2;
      }
      continue;
    }
    out.push(c);
    i++;
  }
  return out.join("");
}

function stripCommentsAndStrings(source: string): string {
  const out: string[] = [];
  let i = 0;
  const n = source.length;
  while (i < n) {
    const c = source[i]!;
    const next = source[i + 1];
    if (c === "/" && next === "/") {
      out.push("  ");
      i += 2;
      while (i < n && source[i] !== "\n") {
        out.push(" ");
        i++;
      }
      continue;
    }
    if (c === "/" && next === "*") {
      out.push("  ");
      i += 2;
      while (i < n && !(source[i] === "*" && source[i + 1] === "/")) {
        out.push(source[i] === "\n" ? "\n" : " ");
        i++;
      }
      if (i < n) {
        out.push("  ");
        i += 2;
      }
      continue;
    }
    if (c === "'" || c === '"') {
      const quote = c;
      out.push(" ");
      i++;
      while (i < n && source[i] !== quote) {
        if (source[i] === "\\" && i + 1 < n) {
          out.push("  ");
          i += 2;
          continue;
        }
        out.push(source[i] === "\n" ? "\n" : " ");
        i++;
      }
      if (i < n) {
        out.push(" ");
        i++;
      }
      continue;
    }
    if (c === "`") {
      out.push(" ");
      i++;
      let depth = 0;
      while (i < n) {
        const ch = source[i]!;
        if (depth === 0 && ch === "`") break;
        if (ch === "\\" && i + 1 < n) {
          out.push("  ");
          i += 2;
          continue;
        }
        if (ch === "$" && source[i + 1] === "{") {
          depth++;
          out.push("${");
          i += 2;
          continue;
        }
        if (depth > 0 && ch === "}") {
          depth--;
          out.push("}");
          i++;
          continue;
        }
        if (depth > 0) {
          out.push(ch);
          i++;
          continue;
        }
        out.push(ch === "\n" ? "\n" : " ");
        i++;
      }
      if (i < n) {
        out.push(" ");
        i++;
      }
      continue;
    }
    out.push(c);
    i++;
  }
  return out.join("");
}

import type { ActionRpcRequest } from "./sdk";

// Fits an 8 MiB attachment encoded as base64, including its JSON metadata.
const MAX_ACTION_BYTES = 12 * 1024 * 1024;

export class ActionRequestError extends Error {
  constructor(message: string, readonly status: number) { super(message); }
}

export async function readActionRequest(request: Request): Promise<ActionRpcRequest | { kind: "catalog" }> {
  if (request.headers.get("content-type")?.split(";", 1)[0]?.trim().toLowerCase() !== "application/json") {
    throw new ActionRequestError("Request body must be JSON", 415);
  }
  const reader = request.body?.getReader();
  if (!reader) throw new ActionRequestError("Request body is required", 400);
  const chunks: Uint8Array[] = [];
  let length = 0;
  try {
    for (;;) {
      const { value, done } = await reader.read();
      if (done) break;
      length += value.byteLength;
      if (length > MAX_ACTION_BYTES) {
        await reader.cancel();
        throw new ActionRequestError("Action request exceeds 12 MiB", 413);
      }
      chunks.push(value);
    }
  } finally {
    reader.releaseLock();
  }
  const bytes = new Uint8Array(length);
  let offset = 0;
  for (const chunk of chunks) { bytes.set(chunk, offset); offset += chunk.byteLength; }
  let body: unknown;
  try { body = JSON.parse(new TextDecoder("utf-8", { fatal: true }).decode(bytes)); }
  catch { throw new ActionRequestError("Request body must be JSON", 400); }
  if (!body || typeof body !== "object" || Array.isArray(body)) {
    throw new ActionRequestError("Action request must be an object", 400);
  }
  const payload = body as Record<string, unknown>;
  if (payload.kind !== undefined) {
    if (payload.kind === "catalog" && Object.keys(payload).length === 1) return { kind: "catalog" };
    throw new ActionRequestError("Invalid action request kind", 400);
  }
  if (typeof payload.action !== "string" || !payload.action.trim() || payload.action.length > 128) {
    throw new ActionRequestError("Invalid action name", 400);
  }
  if (payload.actionCallId !== undefined &&
      (typeof payload.actionCallId !== "string" || !/^[a-zA-Z0-9_-]{1,128}$/.test(payload.actionCallId))) {
    throw new ActionRequestError("Invalid action call ID", 400);
  }
  return payload as unknown as ActionRpcRequest;
}

// Actions for this artifact. One file, one exported `Actions` map.
//
// Each action has a zod Request/Response schema and a handler. The handler
// receives a typed `ctx` (see `@hatch/space-sdk`) with:
//   ctx.db<typeof schema>()  — drizzle-orm DB instance, typed by your schema
//   ctx.agent.send           — Muse agent handoff for research, web search,
//                             tool use, or multi-step investigation
//   ctx.inference            — direct model-only inference for bounded
//                             transformations: extraction, classification,
//                             summarization, formatting, JSON generation
//   ctx.blobs                — placeholder blob storage API for action-owned
//                             binary data (put/getUrl/delete/head/list)
//   ctx.emit                 — streaming responses (defineStreamingAction only)
//   ctx.invalidateQueries    — notify all clients to refetch data after writes
//
// `satisfies ActionsModule` enforces that every value in `Actions` is a real
// action (not a stray helper) without widening the type — call-site typing
// on the client stays precise per-action.
//
// The client picks up types from this file via
// `import type { Actions } from "../../server/src/actions"`.

import { defineAction, z, type ActionsModule } from "@hatch/space-sdk";
import { desc } from "drizzle-orm";
import * as schema from "./schema";

export const Actions = {
  listEntries: defineAction({
    request: z.object({
      limit: z.number().int().positive().max(100).default(20),
    }),
    response: z.object({
      entries: z.array(
        z.object({
          id: z.number(),
          text: z.string(),
          created_at: z.string(),
        }),
      ),
    }),
    async handler(ctx, args) {
      const db = ctx.db<typeof schema>();
      const rows = await db
        .select()
        .from(schema.entries)
        .orderBy(desc(schema.entries.id))
        .limit(args.limit);
      return {
        entries: rows.map((row) => ({
          id: row.id,
          text: row.text,
          created_at: row.createdAt.toISOString(),
        })),
      };
    },
  }),

  addEntry: defineAction({
    request: z.object({ text: z.string().min(1) }),
    response: z.object({ id: z.number() }),
    async handler(ctx, args) {
      const db = ctx.db<typeof schema>();
      const result = await db
        .insert(schema.entries)
        .values({ text: args.text })
        .returning({ id: schema.entries.id });
      const inserted = result[0];
      if (!inserted) {
        throw new Error("addEntry: insert returned no rows");
      }
      // Notify all clients to refetch after this write.
      ctx.invalidateQueries();
      return { id: inserted.id };
    },
  }),
} satisfies ActionsModule;

const MAX_REQUEST_FRAME_BYTES = 4 * 1024 * 1024;
const MAX_RESPONSE_FRAME_BYTES = 4 * 1024 * 1024;

export function encodeWebSearchFrame(value: unknown): Buffer {
  const payload = Buffer.from(JSON.stringify(value), "utf8");
  if (payload.length > MAX_REQUEST_FRAME_BYTES) {
    throw new Error(`artifact web search request frame too large: ${payload.length} bytes`);
  }
  const frame = Buffer.allocUnsafe(4 + payload.length);
  frame.writeUInt32BE(payload.length, 0);
  payload.copy(frame, 4);
  return frame;
}

export function decodeWebSearchFrame<T>(buffer: Buffer): T {
  if (buffer.length < 4) {
    throw new Error("artifact web search response was truncated");
  }
  const len = buffer.readUInt32BE(0);
  if (len > MAX_RESPONSE_FRAME_BYTES) {
    throw new Error(`artifact web search response frame too large: ${len} bytes`);
  }
  if (buffer.length - 4 < len) {
    throw new Error("artifact web search response ended before full frame arrived");
  }
  return JSON.parse(buffer.subarray(4, 4 + len).toString("utf8")) as T;
}

// Browser-side PDF viewer for generated Muse web artifacts.
//
// Blob downloads deliberately carry CSP `sandbox` so uploaded HTML and SVG
// cannot execute with the artifact's authority. Navigating an iframe directly
// to a PDF blob also applies that sandbox to Chrome's built-in PDF viewer and
// produces a blocked-page error. This component fetches the inert bytes and
// renders them to canvas with PDF.js instead, keeping the response sandbox in
// place.

import {
  createElement,
  useCallback,
  useEffect,
  useRef,
  useState,
  type CSSProperties,
  type ReactElement,
} from "react";
import {
  getDocument,
  version as pdfjsVersion,
  type PDFDocumentLoadingTask,
  type PDFDocumentProxy,
  type RenderTask,
} from "pdfjs-dist";
import "pdfjs-dist/build/pdf.worker.mjs";

const pdfAssetRoot = `./assets/pdfjs/${pdfjsVersion}/`;

export interface PdfViewerLabels {
  /** Status shown while the PDF bytes and document are loading. */
  loading?: string;
  /** Error shown when the PDF cannot be fetched or opened. */
  loadError?: string;
  /** Error shown when the current page cannot be rendered. */
  pageError?: string;
  /** Label for the previous-page button. */
  previousPage?: string;
  /** Label for the next-page button. */
  nextPage?: string;
  /** Visible page-count text. */
  pageIndicator?: (pageNumber: number, totalPages: number) => string;
  /** Complete accessible name for the page-navigation controls. */
  navigationAriaLabel?: string;
  /** Complete accessible name for the rendered page. */
  pageAriaLabel?: (pageNumber: number, totalPages: number) => string;
}

export interface PdfViewerProps {
  /** A fetchable PDF URL, including a URL returned by `ctx.blobs.getUrl()`. */
  src: string;
  /** Accessible name used for the viewer and English default page labels. */
  ariaLabel?: string;
  /** User-visible and accessible labels. Omitted fields use English defaults. */
  labels?: PdfViewerLabels;
  /** Page shown after loading. Values outside the document are clamped. */
  initialPage?: number;
  className?: string;
  style?: CSSProperties;
}

const rootStyle: CSSProperties = {
  display: "grid",
  gap: "0.75rem",
  width: "100%",
};

const toolbarStyle: CSSProperties = {
  alignItems: "center",
  display: "flex",
  gap: "0.5rem",
  justifyContent: "center",
};

const pageFrameStyle: CSSProperties = {
  alignItems: "flex-start",
  display: "flex",
  justifyContent: "center",
  minHeight: "8rem",
  overflow: "auto",
  width: "100%",
};

const statusStyle: CSSProperties = {
  alignItems: "center",
  display: "flex",
  justifyContent: "center",
  minHeight: "8rem",
  textAlign: "center",
};

function clampPage(page: number, total: number): number {
  return Math.min(total, Math.max(1, Math.trunc(page) || 1));
}

/**
 * Render a PDF inside a generated Muse web artifact without navigating a
 * nested document to the raw blob URL.
 *
 * The source is fetched as bytes and handed to PDF.js. PDF evaluation is
 * disabled. PDF.js's worker logic is bundled into the SDK so generated clients
 * can use its main-thread fallback in both standard and confidential builds.
 */
export function PdfViewer({
  src,
  ariaLabel = "PDF document",
  labels,
  initialPage = 1,
  className,
  style,
}: PdfViewerProps): ReactElement {
  const frameRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [document, setDocument] = useState<PDFDocumentProxy | null>(null);
  const [pageNumber, setPageNumber] = useState(1);
  const [frameWidth, setFrameWidth] = useState(0);
  const [loadError, setLoadError] = useState(false);
  const [pageError, setPageError] = useState(false);
  const [rendering, setRendering] = useState(false);

  useEffect(() => {
    const frame = frameRef.current;
    if (frame === null) return;

    const measure = () => setFrameWidth(Math.max(1, Math.floor(frame.clientWidth)));
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(frame);
    return () => observer.disconnect();
  }, []);

  useEffect(() => {
    const controller = new AbortController();
    let loadingTask: PDFDocumentLoadingTask | null = null;
    let active = true;

    setDocument(null);
    setLoadError(false);
    setPageError(false);
    setRendering(false);

    void (async () => {
      const response = await fetch(src, {
        credentials: "same-origin",
        signal: controller.signal,
      });
      if (!response.ok) {
        throw new Error(`PDF request failed with HTTP ${response.status}`);
      }
      const bytes = new Uint8Array(await response.arrayBuffer());
      loadingTask = getDocument({
        data: bytes,
        cMapPacked: true,
        cMapUrl: `${pdfAssetRoot}cmaps/`,
        enableXfa: false,
        isEvalSupported: false,
        standardFontDataUrl: `${pdfAssetRoot}standard_fonts/`,
        useWorkerFetch: true,
        wasmUrl: `${pdfAssetRoot}wasm/`,
      });
      const loaded = await loadingTask.promise;
      if (!active) {
        await loaded.destroy();
        return;
      }
      setPageNumber(clampPage(initialPage, loaded.numPages));
      setDocument(loaded);
    })().catch((error: unknown) => {
      if (active && !(error instanceof DOMException && error.name === "AbortError")) {
        setLoadError(true);
      }
    });

    return () => {
      active = false;
      controller.abort();
      if (loadingTask !== null) {
        void loadingTask.destroy();
      }
    };
  }, [initialPage, src]);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (document === null || canvas === null || frameWidth <= 0) return;

    let active = true;
    let renderTask: RenderTask | null = null;
    setPageError(false);
    setRendering(true);

    void (async () => {
      const page = await document.getPage(pageNumber);
      if (!active) return;
      const baseViewport = page.getViewport({ scale: 1 });
      const cssScale = frameWidth / baseViewport.width;
      const outputScale = Math.min(window.devicePixelRatio || 1, 2);
      const viewport = page.getViewport({ scale: cssScale * outputScale });

      canvas.width = Math.max(1, Math.ceil(viewport.width));
      canvas.height = Math.max(1, Math.ceil(viewport.height));
      canvas.style.width = `${Math.max(1, Math.floor(baseViewport.width * cssScale))}px`;
      canvas.style.height = `${Math.max(1, Math.floor(baseViewport.height * cssScale))}px`;

      renderTask = page.render({ canvas, viewport });
      await renderTask.promise;
      if (active) setRendering(false);
    })().catch((error: unknown) => {
      if (active && !(error instanceof Error && error.name === "RenderingCancelledException")) {
        setPageError(true);
        setRendering(false);
      }
    });

    return () => {
      active = false;
      renderTask?.cancel();
    };
  }, [document, frameWidth, pageNumber]);

  const previousPage = useCallback(() => {
    setPageNumber((page) => Math.max(1, page - 1));
  }, []);
  const nextPage = useCallback(() => {
    setPageNumber((page) =>
      document === null ? page : Math.min(document.numPages, page + 1),
    );
  }, [document]);

  const status = loadError
    ? createElement(
        "div",
        { role: "alert", style: statusStyle },
        labels?.loadError ?? "This PDF couldn’t be loaded.",
      )
    : document === null
      ? createElement(
          "div",
          { role: "status", style: statusStyle },
          labels?.loading ?? "Loading PDF…",
        )
      : pageError
        ? createElement(
            "div",
            { role: "alert", style: statusStyle },
            labels?.pageError ?? "This PDF page couldn’t be rendered.",
          )
        : null;

  return createElement(
    "section",
    {
      "aria-label": ariaLabel,
      className,
      style: { ...rootStyle, ...style },
    },
    document !== null && document.numPages > 1
      ? createElement(
          "nav",
          {
            "aria-label": labels?.navigationAriaLabel ?? `${ariaLabel} pages`,
            style: toolbarStyle,
          },
          createElement(
            "button",
            {
              type: "button",
              disabled: pageNumber <= 1,
              onClick: previousPage,
            },
            labels?.previousPage ?? "Previous",
          ),
          createElement(
            "span",
            null,
            labels?.pageIndicator?.(pageNumber, document.numPages) ??
              `Page ${pageNumber} of ${document.numPages}`,
          ),
          createElement(
            "button",
            {
              type: "button",
              disabled: pageNumber >= document.numPages,
              onClick: nextPage,
            },
            labels?.nextPage ?? "Next",
          ),
        )
      : null,
    createElement(
      "div",
      { ref: frameRef, style: pageFrameStyle },
      status,
      createElement("canvas", {
        ref: canvasRef,
        role: "img",
        "aria-label":
          labels?.pageAriaLabel?.(pageNumber, document?.numPages ?? 1) ??
          `${ariaLabel}, page ${pageNumber}`,
        "aria-busy": rendering,
        hidden: document === null || loadError || pageError,
        style: { display: "block", maxWidth: "100%" },
      }),
    ),
  );
}

// Canonical client bundler for Hatch TS spaces. Owned by the SDK so every
// space produces an identical, production-mode React bundle regardless of
// when it was scaffolded.
//
// Invoked from a space's `client/build.mjs` shim:
//
//   import { buildClient } from "@hatch/space-sdk/build";
//   await buildClient();
//
// Bundles `client/index.html` to `client/dist/`. Asset naming matches the
// daemon's `/spaces/v2/<slug>/assets/*` route. NODE_ENV is forced to
// "production" so React's dev-only paths are tree-shaken out.

import { cp, rm } from "node:fs/promises";
import { basename, join } from "node:path";
import tailwindPlugin from "bun-plugin-tailwind";

const ENTRY = "./client/index.html";
const OUTDIR = "./client/dist";
const PDFJS_ASSET_ROOT = "./assets/pdfjs/";

export interface BuildClientOptions {
  // Reserved for future per-web-artifact build customization. No fields are
  // supported today; defaults are intentionally locked down to keep
  // production bundles consistent across web artifacts.
}

export async function buildClient(_options: BuildClientOptions = {}): Promise<void> {
  // =============================== STOP ===============================
  // If you are an agent who hit the error below: editing or deleting this
  // guard, or setting HATCH_SPACES_BUILD_DRIVER yourself, is the WRONG fix
  // and leaves a broken, unpublished Space.
  //
  // A web artifact is built, verified, and published ONLY by the
  // artifact create tools and `artifact.edit`, which run the full pipeline
  // (migrations, typecheck, client + server bundle, manifest, icon,
  // screenshot verification, registration, publish) inside a builder
  // subagent. Running the build by hand compiles source but does NOT migrate,
  // verify, register, or deploy anything, so your changes never reach the
  // live web artifact.
  //
  // To change this web artifact, call the `artifact.edit` tool. To make a new
  // one, call `artifact.create_web_static` or `artifact.create_web_fullstack`.
  // ====================================================================
  if (process.env.HATCH_SPACES_BUILD_DRIVER !== "1") {
    console.error(
      "This web artifact cannot be built by hand. To make this change, call the `artifact.edit` tool " +
        "(or `artifact.create_web_static` / `artifact.create_web_fullstack` for a new one); it rebuilds and re-publishes the web artifact " +
        "automatically. Speak to the user as you would about any edit you are " +
        "making for them: conversational, focused on what is changing and that it " +
        "will be ready shortly.",
    );
    process.exit(1);
  }

  if (typeof Bun === "undefined" || typeof Bun.build !== "function") {
    throw new Error("buildClient() must run under Bun");
  }

  await rm(OUTDIR, { force: true, recursive: true });

  const result = await Bun.build({
    entrypoints: [ENTRY],
    outdir: OUTDIR,
    minify: true,
    define: {
      "process.env.NODE_ENV": JSON.stringify("production"),
    },
    naming: {
      asset: "assets/[name]-[hash].[ext]",
      chunk: "assets/[name]-[hash].[ext]",
      entry: "[name].[ext]",
    },
    plugins: [tailwindPlugin],
  });

  if (!result.success) {
    for (const log of result.logs) {
      console.error(log);
    }
    throw new Error("buildClient() failed; see logged diagnostics");
  }

  // Bun writes imported assets to `naming.asset` (`assets/<name>-<hash>.<ext>`)
  // but emits the JS/CSS import URL as a bare `./<name>-<hash>.<ext>` — without
  // the `assets/` directory prefix. The browser then resolves it against the
  // document base (`/spaces/v2/<slug>/`) and requests `/spaces/v2/<slug>/<file>`,
  // which 404s because the daemon only serves built files under `/assets/`.
  // (Bun's `publicPath` would fix asset URLs but double-prefixes the entry/chunk
  // refs, which already carry `assets/` from `naming.chunk`.) Re-prefix only the
  // bare imported-asset URLs to `./assets/...`. This is idempotent
  // (`./assets/<f>` does not contain `./<f>`) and never rewrites chunk refs.
  // Keep `assets/` in sync with `naming.asset` above.
  const assetFiles = result.outputs
    .filter((output) => output.kind === "asset")
    .map((output) => basename(output.path));
  let needsPdfjsAssets = false;
  for (const output of result.outputs) {
    if (!/\.(js|css|html)$/.test(output.path)) {
      continue;
    }
    let text = await output.text();
    needsPdfjsAssets ||= text.includes(PDFJS_ASSET_ROOT);
    let changed = false;
    for (const name of assetFiles) {
      const bare = `./${name}`;
      if (text.includes(bare)) {
        text = text.split(bare).join(`./assets/${name}`);
        changed = true;
      }
    }
    if (changed) {
      await Bun.write(output.path, text);
    }
  }

  if (needsPdfjsAssets) {
    await cp(join(import.meta.dir, "pdfjs-assets"), join(OUTDIR, "assets", "pdfjs"), {
      recursive: true,
    });
  }
}

import type { LibSQLDatabase } from "drizzle-orm/libsql";
import { z } from "zod";

export { z };

/** A loose JSON value used by streaming `ctx.emit` frames. */
export type JsonValue =
  | string
  | number
  | boolean
  | null
  | JsonValue[]
  | { [key: string]: JsonValue };

/**
 * Portable typed drizzle-orm DB surface for Muse Spaces.
 *
 * The schema TYPE flows from the agent's call site into Drizzle's query
 * types; no schema VALUE crosses into the SDK or worker. Local runtime uses
 * `drizzle-orm/libsql`; Cloudflare runtime uses `drizzle-orm/d1`.
 *
 * This is the conservative portable subset supported across both runtimes.
 * Use `batch` for simple atomic multi-statement write sets. Do not expose
 * `transaction` here: D1 rejects Drizzle's SQL BEGIN/SAVEPOINT transaction
 * implementation from Worker bindings.
 */
export type SpaceDb<
  TSchema extends Record<string, unknown> = Record<string, never>,
> = Pick<
  LibSQLDatabase<TSchema>,
  "select" | "insert" | "update" | "delete" | "run" | "all" | "get" | "batch"
>;

/** Per-invocation typed DB accessor. */
export type SpaceDbAccessor = <
  TSchema extends Record<string, unknown> = Record<string, never>,
>() => SpaceDb<TSchema>;

/** User identity verified by the local daemon, without a share token. */
export type LocalViewer = {
  source: "local";
  authenticated: true;
  spaceSlug: string;
  userId: string;
  ownerUserId: string;
  isOwner: boolean;
  /** Native Muse delegation, distinct from the owner's browser. */
  delegate?: "agent" | "schedule";
};

export type CloudflareViewer = {
  source: "cloudflare";
  authenticated: true;
  shareId: string;
  spaceSlug: string;
  spaceId?: string;
  viewerFbid: string;
  ownerFbid: string;
  isOwner: boolean;
  tokenExpiresAt: number;
  tokenId: string;
  displayName?: string;
};

export type Viewer = LocalViewer | CloudflareViewer;

export type BlobPutData = string | ArrayBuffer | ArrayBufferView | Blob;

export interface BlobPutOptions {
  readonly contentType?: string;
  readonly public?: boolean;
}

export interface BlobUrlOptions {
  readonly expiresInSeconds?: number;
  readonly public?: boolean;
}

export interface BlobMetadata {
  readonly key: string;
  readonly contentType: string;
  readonly size: number;
  readonly sizeBytes: number;
  readonly etag: string;
  readonly visibility: "private" | "public";
  readonly createdAtMs: number;
  readonly updatedAtMs: number;
  readonly public: boolean;
}

export interface BlobClient {
  put(key: string, data: BlobPutData, options?: BlobPutOptions): Promise<void>;
  getUrl(key: string, options?: BlobUrlOptions): Promise<string>;
  delete(key: string): Promise<void>;
  head(key: string): Promise<BlobMetadata | null>;
  list(prefix?: string): Promise<BlobMetadata[]>;
}

/**
 * Versioned brand for privileged function descriptors.
 *
 * Descriptors are the portable contract that action code imports and passes to
 * `ctx.executePrivileged(...)`. Host-capable implementations live in a
 * separate privileged bundle; action bundles should only carry descriptors.
 */
export const PRIVILEGED_CONTRACT_BRAND =
  "@hatch/space-sdk/privileged-contract/v1" as const;

export interface PrivilegedContract<
  Name extends string = string,
  Req extends z.ZodType = z.ZodType,
  Res extends z.ZodType = z.ZodType,
> {
  readonly __brand: typeof PRIVILEGED_CONTRACT_BRAND;
  readonly name: Name;
  readonly request: Req;
  readonly response: Res;
  readonly capabilities?: readonly string[];
  readonly timeoutMs?: number;
}

export type PrivilegedContractSpec<
  Req extends z.ZodType = z.ZodType,
  Res extends z.ZodType = z.ZodType,
> = {
  readonly request: Req;
  readonly response: Res;
  readonly capabilities?: readonly string[];
  readonly timeoutMs?: number;
};

export type PrivilegedContractsFor<
  Specs extends Record<string, PrivilegedContractSpec>,
> = {
  readonly [Name in keyof Specs & string]: PrivilegedContract<
    Name,
    Specs[Name]["request"],
    Specs[Name]["response"]
  >;
};

export type PrivilegedRequest<C extends PrivilegedContract> = z.infer<
  C["request"]
>;
export type PrivilegedResponse<C extends PrivilegedContract> = z.infer<
  C["response"]
>;

export interface PrivilegedExecutor {
  executePrivileged<C extends PrivilegedContract>(
    contract: C,
    args: PrivilegedRequest<C>,
  ): Promise<PrivilegedResponse<C>>;
}

export type PrivilegedTransport = <C extends PrivilegedContract>(
  contract: C,
  args: PrivilegedRequest<C>,
) => Promise<unknown>;

export const PRIVILEGED_HANDLERS_FORMAT =
  "hatch-space-privileged-handlers-v1" as const;

export type PrivilegedHandler<C extends PrivilegedContract = PrivilegedContract> = (
  args: PrivilegedRequest<C>,
) => Promise<PrivilegedResponse<C>> | PrivilegedResponse<C>;

export type PrivilegedHandlersFor<
  Contracts extends Record<string, PrivilegedContract>,
> = {
  readonly [Name in keyof Contracts]?: PrivilegedHandler<Contracts[Name]>;
};

export interface PrivilegedHandlerEntry<C extends PrivilegedContract = PrivilegedContract> {
  readonly contract: C;
  readonly handler: PrivilegedHandler<C>;
}

export interface PrivilegedHandlers {
  readonly format: typeof PRIVILEGED_HANDLERS_FORMAT;
  readonly entries: readonly PrivilegedHandlerEntry[];
}

export function definePrivilegedContracts<
  const Specs extends Record<string, PrivilegedContractSpec>,
>(specs: Specs): PrivilegedContractsFor<Specs> {
  const contracts: Record<string, PrivilegedContract> = {};
  for (const [name, spec] of Object.entries(specs)) {
    contracts[name] = {
      __brand: PRIVILEGED_CONTRACT_BRAND,
      name,
      request: spec.request,
      response: spec.response,
      ...(spec.capabilities !== undefined
        ? { capabilities: spec.capabilities }
        : {}),
      ...(spec.timeoutMs !== undefined ? { timeoutMs: spec.timeoutMs } : {}),
    };
  }
  return contracts as PrivilegedContractsFor<Specs>;
}

export function definePrivilegedHandlers<
  const Contracts extends Record<string, PrivilegedContract>,
>(
  contracts: Contracts,
  handlers: PrivilegedHandlersFor<Contracts>,
): PrivilegedHandlers {
  const entries: PrivilegedHandlerEntry[] = [];
  for (const [key, handler] of Object.entries(handlers)) {
    if (handler === undefined) {
      continue;
    }
    const contract = contracts[key];
    if (!isPrivilegedContract(contract)) {
      throw new Error(`privileged handler '${key}' does not have a contract descriptor`);
    }
    entries.push({
      contract,
      handler: handler as PrivilegedHandler,
    });
  }
  return {
    format: PRIVILEGED_HANDLERS_FORMAT,
    entries,
  };
}

/** Runtime check used by workers to recognize privileged descriptors. */
export function isPrivilegedContract(value: unknown): value is PrivilegedContract {
  return (
    typeof value === "object" &&
    value !== null &&
    "__brand" in value &&
    (value as { __brand: unknown }).__brand === PRIVILEGED_CONTRACT_BRAND
  );
}

export function isPrivilegedHandlers(value: unknown): value is PrivilegedHandlers {
  return (
    typeof value === "object" &&
    value !== null &&
    "format" in value &&
    (value as { format: unknown }).format === PRIVILEGED_HANDLERS_FORMAT &&
    Array.isArray((value as { entries?: unknown }).entries)
  );
}

export function createPrivilegedExecutor(
  declared: readonly PrivilegedContract[] | undefined,
  transport: PrivilegedTransport,
): PrivilegedExecutor {
  const declaredNames = new Set((declared ?? []).map((contract) => contract.name));
  return {
    async executePrivileged<C extends PrivilegedContract>(
      contract: C,
      args: PrivilegedRequest<C>,
    ): Promise<PrivilegedResponse<C>> {
      if (!isPrivilegedContract(contract)) {
        throw new Error("ctx.executePrivileged requires a privileged contract descriptor");
      }
      if (!declaredNames.has(contract.name)) {
        throw new Error(
          `ctx.executePrivileged(${contract.name}) was not declared by this action`,
        );
      }
      const parsedArgs = contract.request.parse(args) as PrivilegedRequest<C>;
      const result = await transport(contract, parsedArgs);
      return contract.response.parse(result) as PrivilegedResponse<C>;
    },
  };
}

/** Runtime-neutral context fields available to portable Space actions. */
export interface PortableCtx extends PrivilegedExecutor {
  readonly slug: string;
  readonly invocationId: string;
  readonly spaceDir: string;
  readonly db: SpaceDbAccessor;
  readonly viewer?: Viewer;
  readonly blobs: BlobClient;
}

/**
 * Versioned brand. Identifies a value as an action definition produced by
 * `defineAction(...)`. The worker scans module exports for objects carrying
 * this brand to build its dispatch table.
 *
 * Versioning lets a future SDK reject stale-shape actions explicitly. The
 * string shape is stable across independently bundled SDK copies; avoid Symbol
 * identity here because Cloudflare and local bundles intentionally inline
 * separate module copies.
 */
export const ACTION_BRAND = "@hatch/space-sdk/action/v1" as const;
const LEGACY_ACTION_BRAND = Symbol.for("@hatch/space-sdk/action");

export interface ActionDefinition<
  TCtx extends PortableCtx = PortableCtx,
  Req extends z.ZodType = z.ZodType,
  Res extends z.ZodType = z.ZodType,
> {
  readonly __brand: typeof ACTION_BRAND;
  readonly request: Req;
  readonly response: Res;
  readonly privileged?: readonly PrivilegedContract[];
  readonly handler: (ctx: TCtx, args: z.infer<Req>) => Promise<z.infer<Res>>;
}

export type ActionFactoryInput<
  TCtx extends PortableCtx,
  Req extends z.ZodType,
  Res extends z.ZodType,
> = {
  request: Req;
  response: Res;
  privileged?: readonly PrivilegedContract[];
  handler: (ctx: TCtx, args: z.infer<Req>) => Promise<z.infer<Res>>;
};

/** Bind the shared action implementation to a runtime-specific Ctx type. */
export function createDefineAction<TCtx extends PortableCtx>() {
  return function defineAction<Req extends z.ZodType, Res extends z.ZodType>(
    spec: ActionFactoryInput<TCtx, Req, Res>,
  ): ActionDefinition<TCtx, Req, Res> {
    return {
      __brand: ACTION_BRAND,
      request: spec.request,
      response: spec.response,
      ...(spec.privileged !== undefined ? { privileged: spec.privileged } : {}),
      handler: spec.handler,
    };
  };
}

/** Runtime check used by workers to filter module exports. */
export function isAction(value: unknown): value is ActionDefinition {
  if (typeof value !== "object" || value === null) {
    return false;
  }
  if (
    "__brand" in value &&
    (value as { __brand: unknown }).__brand === ACTION_BRAND
  ) {
    return true;
  }
  return (
    (value as { kind?: unknown }).kind === "action" &&
    (value as { [LEGACY_ACTION_BRAND]?: unknown })[LEGACY_ACTION_BRAND] === true
  );
}

/**
 * The shape every space's `actions.ts` must satisfy. Use as
 * `} satisfies ActionsModule;` to flag stray non-action values without
 * widening the inferred type.
 */
export type ActionsModuleFor<TCtx extends PortableCtx> = Record<
  string,
  Omit<ActionDefinition<TCtx>, "handler"> & {
    handler: (ctx: TCtx, args: any) => Promise<any>;
  }
>;

/** Extract the request payload type for a given action. */
export type ActionRequest<A extends { request: z.ZodType }> = z.infer<A["request"]>;

/** Extract the response payload type for a given action. */
export type ActionResponse<A extends { response: z.ZodType }> = z.infer<A["response"]>;

